var app=TwinInspector.AppBootstrap.Instance;
if(app==null || !app.Ready) throw new System.Exception("Application is not ready");
if(app.Loader.Failures!=0 || app.Loader.LoadedTiles<1 || app.Loader.Triangles>1200000) throw new System.Exception("Streaming gate failed");
var result=new System.Text.StringBuilder();
foreach(TwinInspector.ViewMode mode in System.Enum.GetValues(typeof(TwinInspector.ViewMode))) { app.Style.SetMode(mode); if(app.Style.Mode!=mode) throw new System.Exception("Mode did not switch"); }
app.Style.SetBlend(.64f); if(UnityEngine.Mathf.Abs(UnityEngine.Shader.GetGlobalFloat("_TwinAlpha")-.64f)>.001) throw new System.Exception("Blend did not update");
app.Style.SetBlend(.45f); result.AppendLine("PASS: three view modes and global alpha");
var position=app.Root.transform.position; var rotation=app.Root.transform.rotation;
app.Manual.HeightUnlocked=false; app.Manual.Nudge(.01f,-.05f,1,2);
if(UnityEngine.Mathf.Abs(app.Root.transform.position.y-position.y)>.0001f) throw new System.Exception("Height lock failed");
app.Root.transform.SetPositionAndRotation(position,rotation); result.AppendLine("PASS: manual nudge and height lock");
app.Markers.SimulateFirst(); if(!app.Markers.AwaitingConfirmation) throw new System.Exception("Marker simulation failed"); app.Markers.Cancel();
if(UnityEngine.Vector3.Distance(position,app.Root.transform.position)>.0001) throw new System.Exception("Marker cancel failed"); result.AppendLine("PASS: marker simulation and cancel");
var point=app.Root.WorldToTwin(app.Viewer.transform.position+app.Viewer.transform.forward*2);
var item=app.Annotations.Add(point,UnityEngine.Vector3.forward,app.Root.WorldToTwin(app.Viewer.transform.position),app.Root.RotationToTwin(app.Viewer.transform.rotation));
item.comment="Editor QA fixture; removed after verification";
app.Annotations.Retype(TwinInspector.AnnotationType.Changed);
var restarted=new TwinInspector.AnnotationStore(app.Loader.Manifest.scan);
if(restarted.Items.Count!=app.Annotations.Items.Count || restarted.Items[restarted.Items.Count-1].type!="changed") throw new System.Exception("Annotation reload failed");
string export=TwinInspector.AnnotationExporter.Export(app.Annotations);
if(!System.IO.File.Exists(export) || !System.IO.File.Exists(System.IO.Path.ChangeExtension(export,".csv"))) throw new System.Exception("Export failed");
System.IO.Directory.CreateDirectory("docs/evidence");
System.IO.File.Copy(export,"docs/evidence/annotation-export.json",true);
System.IO.File.Copy(System.IO.Path.ChangeExtension(export,".csv"),"docs/evidence/annotation-export.csv",true);
System.IO.File.Delete(export); System.IO.File.Delete(System.IO.Path.ChangeExtension(export,".csv"));
app.Annotations.Select(item.id); app.Annotations.DeleteSelected(); result.AppendLine("PASS: annotation create/select/retype/reload/delete and JSON/CSV export");
result.AppendLine("PASS: "+app.Loader.LoadedTiles+" loaded tiles; "+app.Loader.Triangles+" resident triangles; 0 load failures");
result.AppendLine("Editor checks only; no headset performance or physical tracking claim.");
System.IO.Directory.CreateDirectory("docs/evidence"); System.IO.File.WriteAllText("docs/evidence/editor-smoke.txt",result.ToString());
app.UI.Show("setup"); return result.ToString();
